#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    int waysToPartition(std::vector<int>& nums, int k) {
        int n = nums.size();
        std::vector<long long> pref(n);
        pref[0] = nums[0];
        for (int i = 1; i < n; ++i) pref[i] = pref[i - 1] + nums[i];
        long long total = pref[n - 1];

        std::unordered_map<long long, int> right_diff, left_diff;
        for (int i = 0; i < n - 1; ++i) {
            long long d = 2 * pref[i] - total;
            right_diff[d]++;
        }

        int ans = right_diff[0];
        for (int i = 0; i < n; ++i) {
            long long delta = k - nums[i];
            int curr = left_diff[delta] + right_diff[-delta];
            ans = std::max(ans, curr);
            if (i < n - 1) {
                long long d = 2 * pref[i] - total;
                right_diff[d]--;
                left_diff[d]++;
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int waysToPartition(int[] nums, int k) {
        int n = nums.length;
        long[] pref = new long[n];
        pref[0] = nums[0];
        for (int i = 1; i < n; i++) pref[i] = pref[i - 1] + nums[i];
        long total = pref[n - 1];

        Map<Long, Integer> rightDiff = new HashMap<>();
        Map<Long, Integer> leftDiff = new HashMap<>();

        for (int i = 0; i < n - 1; i++) {
            long d = 2 * pref[i] - total;
            rightDiff.put(d, rightDiff.getOrDefault(d, 0) + 1);
        }

        int ans = rightDiff.getOrDefault(0L, 0);

        for (int i = 0; i < n; i++) {
            long delta = (long) k - nums[i];
            int curr = leftDiff.getOrDefault(delta, 0) + rightDiff.getOrDefault(-delta, 0);
            ans = Math.max(ans, curr);
            if (i < n - 1) {
                long d = 2 * pref[i] - total;
                rightDiff.put(d, rightDiff.get(d) - 1);
                leftDiff.put(d, leftDiff.getOrDefault(d, 0) + 1);
            }
        }
        return ans;
    }
}

